<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('wallet.view');
$q=trim((string)input('q'));$type=strtoupper((string)input('type'));$from=trim((string)input('from'));$to=trim((string)input('to'));$page=page_int();[$limit,$offset]=pagination($page);$where=[];$params=[];
if($q!==''){$where[]='(t.transaction_id LIKE ? OR u.name LIKE ? OR t.reference LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');}if(in_array($type,['CREDIT','DEBIT','WITHDRAWAL','REFUND','ADJUSTMENT','REVERSAL'],true)){$where[]='t.type=?';$params[]=$type;}if($from!==''&&valid_date($from)){$where[]='t.created_at>=?';$params[]=$from;}if($to!==''&&valid_date($to)){$where[]='t.created_at<DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$to;}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';
$count=db()->prepare('SELECT COUNT(*) FROM wallet_transactions t JOIN users u ON u.id=t.user_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT t.*,u.name FROM wallet_transactions t JOIN users u ON u.id=t.user_id'.$sqlWhere.' ORDER BY t.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();$pageTitle='Wallet ledger';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Transactions</h2><?php if(can('wallet.credit')||can('wallet.debit')):?><a class="btn" href="<?=e(app_url('/admin/wallets/adjust.php'))?>">New adjustment</a><?php endif?></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Transaction, user or reference"><select name="type"><option value="">All types</option><?php foreach(['CREDIT','DEBIT','WITHDRAWAL','REFUND','ADJUSTMENT','REVERSAL'] as $s):?><option <?=$type===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>User</th><th>Type</th><th>Amount</th><th>Balance change</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['transaction_id'])?></strong><br><small><?=e($r['reference']??'—')?></small></td><td><a href="<?=e(app_url('/admin/users/view.php?id='.$r['user_id']))?>"><?=e($r['name'])?></a></td><td><?=e($r['type'])?></td><td><?=money($r['amount'])?></td><td><?=money($r['previous_balance'])?> → <?=money($r['new_balance'])?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td><td><a class="btn small secondary" href="<?=e(app_url('/admin/wallets/view.php?id='.$r['id']))?>">View</a></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No transactions found.</div><?php endif?></div><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><a href="?<?=e(http_build_query(['q'=>$q,'type'=>$type,'from'=>$from,'to'=>$to,'page'=>$i]))?>"><?=$i?></a><?php endfor?></div></section><?php require APP_ROOT.'/includes/footer.php';

